frappe.ui.form.on('HR Settings', {
    refresh(frm) {
        toggle_fields(frm);
    },
    custom_track_employee_administrative_ranks(frm) {
        toggle_fields(frm);
    },
    custom_add_option(frm) {
        if (frm.doc.custom_options) {
            // Vérifier si la valeur existe déjà dans la table
            const exists = (frm.doc.custom_options_table || []).some(row => row.options === frm.doc.custom_options);

            if (exists) {
                frappe.msgprint(__('Cette option est déjà présente dans la table.'));
                return;
            }

            // Ajouter la nouvelle ligne
            frm.add_child('custom_options_table', {
                'options': frm.doc.custom_options,
            });

            frm.refresh_field('custom_options_table');

            // Réinitialiser le champ custom_options
            frm.set_value('custom_options', '');
        } else {
            frappe.msgprint(__('Veuillez sélectionner une option avant d\'ajouter.'));
        }
    }
});


function toggle_fields(frm) {
    const visible = frm.doc.custom_track_employee_administrative_ranks == 1;

    frm.toggle_display('custom_options', visible);
    frm.toggle_display('custom_add_option', visible);
    frm.toggle_display('custom_options_table', visible);

    if (visible) {
        frappe.call({
            method: "payrolls.gestion_de_paie.doctype.options.options.get_employee_link_fields",
            callback: function (r) {
                if (r.message) {
                    console.log("Champs Link dans Employee :", r.message);
                    const allowed_doc_types = r.message;

                    frm.fields_dict['custom_options'].get_query = function() {
                        return {
                            filters: [
                                ['name', 'in', allowed_doc_types]
                            ]
                        };
                    };
                }
            }
        });
    }
}

frappe.ui.form.on('Change Administratives infos', {
    refresh(frm) {
        // Charger les champs Link autorisés
        frappe.call({
            method: "payrolls.gestion_de_paie.doctype.change_administratives_infos.change_administratives_infos.check_and_add_admin_info",
            callback: function (r) {
                if (r.message) {
                    const allowed_doc_types = r.message;
                    frm.fields_dict['infos'].get_query = () => ({
                        filters: [['name', 'in', allowed_doc_types]]
                    });
                }
            }
        });

        // Mettre la date du jour
        frm.set_value('current_date', frappe.datetime.get_today());
    },

    infos(frm) {
        frm.clear_table('values');
        frm.refresh_field('values');

        if (frm.doc.employee && frm.doc.company && frm.doc.infos) {
            frappe.call({
                method: "payrolls.gestion_de_paie.doctype.change_administratives_infos.change_administratives_infos.select_all_employees_administratives_infos",
                args: {
                    company: frm.doc.company,
                    employee: frm.doc.employee,
                    elements: frm.doc.infos
                },
                callback: function (r) {
                    if (Array.isArray(r.message)) {
                        r.message.forEach(row => {
                            frm.add_child('values', {
                                employee: row.employee,
                                company: row.company,
                                elements: row.elements,
                                value: row.value,
                                start_date: row.start_date,
                                end_date: row.end_date || null,
                                id_admin_infos: row.name
                            });
                        });
                        frm.refresh_field('values');
                    }
                }
            });
        }
    },

    add_new_value(frm) {
        if (!frm.doc.employee) return frappe.msgprint(__('Veuillez saisir un employé'));
        if (!frm.doc.infos) return frappe.msgprint(__('Veuillez saisir un élément dans Infos'));
        if (!frm.doc.new_value) return frappe.msgprint(__('Veuillez saisir une valeur'));

        let last_row = frm.doc.values.slice(-1)[0];
        if (last_row && last_row.elements === frm.doc.infos && !last_row.end_date) {
            last_row.end_date = frappe.datetime.get_today();
        }

        frm.add_child('values', {
            employee: frm.doc.employee,
            company: frm.doc.company,
            elements: frm.doc.infos,
            value: frm.doc.new_value,
            start_date: frappe.datetime.get_today()
        });
        frm.refresh_field('values');
        frm.set_value('new_value', '');
    },


    before_save(frm) {
        if (!frm.doc.values || frm.doc.values.length === 0) return;

        frappe.call({
            method: "payrolls.gestion_de_paie.doctype.change_administratives_infos.change_administratives_infos.save_admin_info_and_update_employee",
            args: {
                values: JSON.stringify(frm.doc.values),
                employee: frm.doc.employee,
                company: frm.doc.company
            },
            callback: function(r) {
                frappe.msgprint(r.message);
                frm.clear_table('values');
                frm.refresh_field('values');
                frm.set_value('infos', '');
            }
        });
    }

});

frappe.listview_settings['Attendance'] = {
    onload: function(listview) {
        if (!listview.page.custom_buttons_added) {
            listview.page.custom_buttons_added = true;

            // Ajouter un bouton personnalisé dans la barre d'outils
            listview.page.add_inner_button(__('Actualiser Présences'), function() {
                let d = new frappe.ui.Dialog({
                    title: __('Actualiser Présence'),
                    fields: [
                        {
                            label: __('Actualisation'),
                            fieldname: 'actualisation',
                            fieldtype: 'Select',
                            options: ['Tous le monde', 'Individuel'],
                            default: 'Tous le monde',
                            change: function() {
                                let actualisation = this.get_value();
                                if (actualisation === 'Individuel') {
                                    d.set_df_property('employee', 'hidden', false);
                                } else {
                                    d.set_df_property('employee', 'hidden', true);
                                }
                            }
                        },
                        {
                            label: __('Employee'),
                            fieldname: 'employee',
                            fieldtype: 'Link',
                            options: 'Employee',
                            hidden: true, // Masquer par défaut
                            get_query: () => {
                                return {
                                    filters: {
                                        'status': 'Active'
                                    }
                                };
                            }
                        }
                    ],
                    primary_action_label: __('Mettre à jour'),
                    primary_action: function(values) {
                        if (values.actualisation === 'Individuel') {
                            if (!values.employee) {
                                frappe.msgprint(__('Veuillez sélectionner un employé.'));
                                return;
                            }

                            frappe.call({
                                method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.update_attendance_individuel",
                                args: {
                                    employee: values.employee,
                                },
                                callback: function(r) {
                                    if (!r.exc) {
                                        frappe.msgprint(__('Actualisation en cours pour l\'employé sélectionné.'));
                                        listview.refresh();
                                    }
                                }
                            });
                        } else {
                            frappe.call({
                                method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.update_attendance_all",
                                callback: function(r) {
                                    if (!r.exc) {
                                        frappe.msgprint(__('Actualisation en cours pour tous les employés.'));
                                        listview.refresh();
                                    }
                                }
                            });
                        }
                        d.hide();
                    }
                });

                d.show();
            });
        }
    }
};

frappe.ui.form.on('Attendance', {
    refresh(frm) {
        // Utiliser l'événement 'refresh' au lieu de 'insert' pour s'assurer que le code s'exécute correctement
        if (frm.is_new()) { // Vérifier si le formulaire est en mode création
            frm.doc.naming_series = ""; // Réinitialiser le naming_series

            // Récupérer les valeurs nécessaires
            let employee = frm.doc.employee;
            let attendanceDate = frm.doc.attendance_date;

            // Extraire l'année, le mois et le jour de la date
            let year = attendanceDate.slice(2, 4); // YY
            let month = attendanceDate.slice(5, 7); // MM
            let day = attendanceDate.slice(8, 10); // DD

            // Construire le naming_series
            frm.doc.naming_series = `YY-${employee}-${day}${month}${year} 00:00:00`;

            // Rafraîchir le formulaire pour afficher les modifications
            frm.refresh_field('naming_series');
        }
    }
});

